function commonPrefix(words) {
  var prefix = words[0];
  for (var i = 1; i < words.length; i++) {
    while (words[i].indexOf(prefix) !== 0) {
      prefix = prefix.slice(0, -1);
    }
  }
  return prefix;
}

console.log(commonPrefix(["cascade", "cast", "castle"]));
